        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by the lack of a call to `of_node_put()` after obtaining a node pointer with `of_find_compatible_node()`, which increments the reference count. This oversight leads to a reference count leak, as the reference to the node is not released when it is no longer needed.

        Commit message:
        clk: qoriq: fix refcount leak in clockgen_init()

The of_find_compatible_node() returns a node pointer with refcount
incremented, but there is the lack of use of the of_node_put() when
done. Add the missing of_node_put() to release the refcount.

Signed-off-by: Yangtao Li <tiny.windzz@gmail.com>
Fixes: 0dfc86b3173f ("clk: qoriq: Move chip-specific knowledge into driver")
Signed-off-by: Stephen Boyd <sboyd@kernel.org>  

        Patch:

 static void __init clockgen_init(struct device_node *np)
 {
 	int i, ret;
 	bool is_old_ls1021a = false;

 	/* May have already been called by a legacy probe */
 	if (clockgen.node)
 		return;

 	clockgen.node = np;
 	clockgen.regs = of_iomap(np, 0);
 	if (!clockgen.regs &&
 	    of_device_is_compatible(of_root, "fsl,ls1021a")) {
 		/* Compatibility hack for old, broken device trees */
 		clockgen.regs = ioremap(0x1ee1000, 0x1000);
 		is_old_ls1021a = true;
 	}
 	if (!clockgen.regs) {
 		pr_err("%s(): %pOFn: of_iomap() failed\n", __func__, np);
 		return;
 	}

 	for (i = 0; i < ARRAY_SIZE(chipinfo); i++) {
 		if (of_device_is_compatible(np, chipinfo[i].compat))
 			break;
 		if (is_old_ls1021a &&
 		    !strcmp(chipinfo[i].compat, "fsl,ls1021a-clockgen"))
 			break;
 	}

 	if (i == ARRAY_SIZE(chipinfo)) {
 		pr_err("%s: unknown clockgen node %pOF\n", __func__, np);
 		goto err;
 	}
 	clockgen.info = chipinfo[i];

 	if (clockgen.info.guts_compat) {
 		struct device_node *guts;

 		guts = of_find_compatible_node(NULL, NULL,
 					       clockgen.info.guts_compat);
 		if (guts) {
 			clockgen.guts = of_iomap(guts, 0);
 			if (!clockgen.guts) {
 				pr_err("%s: Couldn't map %pOF regs\n", __func__,
 				       guts);
 			}
+			of_node_put(guts);
 		}

 	}

 	if (has_erratum_a4510())
 		clockgen.info.flags |= CG_CMUX_GE_PLAT;

 	clockgen.sysclk = create_sysclk("cg-sysclk");
 	clockgen.coreclk = create_coreclk("cg-coreclk");
 	create_plls(&clockgen);
 	create_muxes(&clockgen);

 	if (clockgen.info.init_periph)
 		clockgen.info.init_periph(&clockgen);

 	ret = of_clk_add_provider(np, clockgen_clk_get, &clockgen);
 	if (ret) {
 		pr_err("%s: Couldn't register clk provider for node %pOFn: %d\n",
 		       __func__, np, ret);
 	}

 	return;
 err:
 	iounmap(clockgen.regs);
 	clockgen.regs = NULL;
 }



